UPDATE public.records SET abstract = 'Podmínky zemědělské výroby v České republice odpovídají ustálenému stavu úplného klimatického systému. Narušením ustáleného stavu úplného klimatického systému změnou některých faktorů, například i z důvodu působení člověka, dochází k proměnám v klimatické situaci. Nový stav nemusí být pro lidstvo a jeho obory hospodaření neutrální. Nepříznivé trendy u sledovaných veličin mají&hellip;' WHERE id = '84a7ce8a-dcc6-4790-a24b-384f05eb6d64' AND (abstract IS NULL OR length(btrim(abstract)) < 20 OR lower(btrim(abstract)) IN ('-','--','.','description','n/a','na','no abstract','no description','none','not available','null','xx'));
